import * as THREE from 'three/webgpu';
import { texture as textureNode, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(
    config.scenePosition?.x ?? 3.2,
    config.scenePosition?.y ?? 1,
    config.scenePosition?.z ?? 0.06
  );

  if (config.sceneRotation) {
    group.rotation.set(
      config.sceneRotation.x ?? 0,
      config.sceneRotation.y ?? 0,
      config.sceneRotation.z ?? 0
    );
  }

  if (config.sceneScale) {
    group.scale.set(
      config.sceneScale.x ?? 1,
      config.sceneScale.y ?? 1,
      config.sceneScale.z ?? 1
    );
  }

  // Plane geometry: atlas rect 512x320 → 1.6:1 aspect ratio
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);

  // Load texture
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // TSL material
  const colorNode = textureNode(texture, uv());
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Text via font atlas
  const textContent = config.textContent?.[0] ?? 'Journal 3';
  const inkColor = parseInt(config.colors?.ink?.replace('#', '') ?? '16161d', 16);

  const textMesh = ctx.fontAtlas.createText({
    text: textContent,
    size: 0.34, // headline scale
    weight: 400,
    font: 'display', // Lora serif
    color: inkColor,
    anchor: { x: 0.5, y: 0.5 },
  });

  if (textMesh) {
    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Animation state
  const baseY = group.position.y;
  let hoverTimeline = null;

  // Event handlers
  group.userData.handlers = {
    pointerenter: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    pointerleave: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out',
      });
    },
    click: () => {
      if (config.emitEvent) {
        config.emitEvent('hub-journal.select', {});
      }
    },
  };

  // Cleanup
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    texture.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
  };

  return group;
}
